// Independent auditor database probe: migration history in both managed databases equals the
// checked-in bytes, 0001 is byte-identical to main, and only the match runtime role (plus the
// owning migrator) holds privileges on the new private match tables; no PUBLIC/api/worker access.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { client } from './packages/db/dist/index.js';

const files = ['0001-foundation-probes.sql', '0002-match-commands.sql', '0003-match-receipt-invariants.sql'].map(name => {
  const bytes = readFileSync('packages/db/migrations/' + name); return { id: name.slice(0, 4), name, sha256: createHash('sha256').update(bytes).digest('hex') };
});
const mainBytes = execFileSync('git', ['show', '9b9c8ac:packages/db/migrations/0001-foundation-probes.sql']);
assert.equal(createHash('sha256').update(mainBytes).digest('hex'), files[0].sha256, '0001 changed since main');
const tables = ['releases', 'matches', 'command_receipts', 'journal', 'outbox'];
const out = {};
for (const target of ['local', 'test']) {
  const c = client(target, 'migrator'); await c.connect();
  try {
    const rows = (await c.query('SELECT id,sha256 FROM foundation.migrations ORDER BY id')).rows;
    assert.deepEqual(rows.map(r => [r.id, r.sha256]), files.map(f => [f.id, f.sha256]), target + ' migration history');
    const roles = { migrator: `lorcana_${target}_migrator`, api: `lorcana_${target}_api`, match: `lorcana_${target}_match`, worker: `lorcana_${target}_worker` };
    const other = target === 'local' ? 'test' : 'local';
    for (const t of tables) {
      const owner = (await c.query("SELECT tableowner FROM pg_tables WHERE schemaname='match' AND tablename=$1", [t])).rows[0]?.tableowner;
      assert.equal(owner, roles.migrator, target + ' owner ' + t);
      for (const [name, role] of Object.entries(roles)) {
        const p = (await c.query("SELECT has_table_privilege($1,$2,'SELECT') s, has_table_privilege($1,$2,'INSERT') i, has_table_privilege($1,$2,'UPDATE') u, has_table_privilege($1,$2,'DELETE') d", [role, 'match.' + t])).rows[0];
        if (name === 'api' || name === 'worker') assert.deepEqual([p.s, p.i, p.u, p.d], [false, false, false, false], target + ' ' + name + ' ' + t);
        if (name === 'match') assert.deepEqual([p.s, p.i, p.u, p.d], [true, true, true, true], target + ' match ' + t);
      }
      const pub = (await c.query("SELECT count(*)::int n FROM information_schema.role_table_grants WHERE table_schema='match' AND table_name=$1 AND grantee='PUBLIC'", [t])).rows[0].n;
      assert.equal(pub, 0, target + ' PUBLIC grant on ' + t);
      // Cross-environment roles exist in the cluster but have no privilege here.
      const foreign = (await c.query("SELECT has_table_privilege($1,$2,'SELECT') s", [`lorcana_${other}_match`, 'match.' + t])).rows[0].s;
      assert.equal(foreign, false, target + ' cross-environment match role on ' + t);
    }
    const constraints = (await c.query("SELECT conname FROM pg_constraint WHERE conrelid='match.command_receipts'::regclass AND contype='c' ORDER BY conname")).rows.map(r => r.conname);
    for (const n of ['command_receipts_actor_identity', 'command_receipts_command_identity', 'command_receipts_outcome_reason']) assert.ok(constraints.includes(n), target + ' missing ' + n);
    assert.equal(constraints.includes('command_receipts_check'), false);
    const terminal = (await c.query("SELECT indexdef FROM pg_indexes WHERE schemaname='match' AND indexname='match_one_terminal_event'")).rows[0]?.indexdef ?? '';
    assert.match(terminal, /UNIQUE INDEX .* \(match_id\) WHERE \(\(kind\)::text = 'match_completed'::text\)/);
    out[target] = { migrations: rows.length, tables: tables.length, constraints: constraints.length };
  } finally { await c.end(); }
  // The api and worker logins really are refused at query time.
  for (const id of ['api', 'worker']) {
    const c2 = client(target, id); await c2.connect();
    try { for (const t of tables) await assert.rejects(c2.query('SELECT 1 FROM match.' + t + ' LIMIT 1'), e => e.code === '42501', target + ' ' + id + ' ' + t); }
    finally { await c2.end(); }
  }
}
console.log(JSON.stringify({ migrations: files.map(f => f.id + ':' + f.sha256.slice(0, 12)), main0001Unchanged: true, ...out }));
console.log('PASS auditor PLAY-01 database probe: local and test histories equal the three checked-in migrations (0001 byte-identical to main); match tables owned by the migrator, full CRUD only for the match role, no api/worker/PUBLIC/cross-environment access; 0003 constraints and the single-terminal-event index present');
